namespace App\Domain\Pricing;

use DateTimeImmutable;

final class PriceCalculator
{
    private const SCALE = 20;          // intermediate scale (>= 16 per requirement)
    private const MONEY_SCALE = 6;     // final rounding scale
    private const PER_MILLION = 1000000;

    /** @param array<string,int> $tokens key: input|output|cache_read|cache_write */
    public function computeBaseCost(string $unit, array $rates, array $tokens): string
    {
        $cost = '0';
        if ($unit === self::UNIT_PER_TOKEN) {
            foreach (self::PER_TOKEN_KINDS as $kind) {
                $cost = $this->bcAdd($cost, $this->tokenCost($tokens[$kind], $rates[$kind]));
            }
        } elseif ($unit === self::UNIT_UNIFIED) {
            $total = 0;
            foreach (self::PER_TOKEN_KINDS as $kind) {
                $total += (int) $tokens[$kind];
            }
            $cost = $this->bcAdd($cost, $this->tokenCost($total, $rates['any']));
        }
        return $cost;
    }

    private function tokenCost(int $tokens, string $rate): string
    {
        // tokens * rate / 1e6, no rounding at intermediate scale
        return bcdiv(bcmul((string) $tokens, $rate, self::SCALE), (string) self::PER_MILLION, self::SCALE);
    }

    public function applyOffPeak(string $cost, ?string $multiplier): string
    {
        if ($multiplier === null || $multiplier === '1') {
            return $cost;
        }
        return bcmul($cost, $multiplier, self::SCALE);
    }

    public function roundToMoney(string $cost): string
    {
        $rounded = bcround($cost, self::MONEY_SCALE, BC_ROUND_HALF_UP);
        return $this->format6($rounded);
    }

    public function isOffPeak(?string $windowStart, ?string $windowEnd, DateTimeImmutable $ts): bool
    {
        if ($windowStart === null || $windowEnd === null) {
            return false;
        }
        $t = $ts->format('H') * 60 + (int) $ts->format('i');
        $s = $this->parseTimeToMinutes($windowStart);
        $e = $this->parseTimeToMinutes($windowEnd);
        if ($s === null || $e === null) {
            return false;
        }
        if ($s <= $e) {
            return $t >= $s && $t < $e;
        }
        // crosses midnight
        return $t >= $s || $t < $e;
    }

    private function parseTimeToMinutes(string $time): ?int
    {
        // HH:MM
        $parts = explode(':', $time);
        if (count($parts) !== 2) return null;
        $h = (int) $parts[0];
        $m = (int) $parts[1];
        if ($h < 0 || $h > 23 || $m < 0 || $m > 59) return null;
        return $h * 60 + $m;
    }

    private function format6(string $v): string
    {
        if (str_contains($v, '.')) {
            [$int, $frac] = explode('.', $v, 2);
        } else {
            $int = $v;
            $frac = '';
        }
        $frac = str_pad($frac, 6, '0', STR_PAD_RIGHT);
        $frac = substr($frac, 0, 6);
        return $int . '.' . $frac;
    }

    private function bcAdd(string $a, string $b): string { return bcadd($a, $b, self::SCALE); }
}
